#include "CAVApp.h"

#include <chrono>
#include <cstdlib>
#include <fstream>
#include <omnetpp.h>

using namespace omnetpp;
namespace cavpqc {
namespace { constexpr int VEHICLE_HELLO=1, SERVER_HELLO=2, FINISHED=3, FULL_ACK=4, HANDOVER_OFFER=10, HANDOVER_REQUEST=11, HANDOVER_CONFIRM=12, HANDOVER_FALLBACK=13; std::int64_t nowMs(simtime_t t) { return static_cast<std::int64_t>(t.dbl()*1000.0); } Bytes text(const std::string& s) { return Bytes(s.begin(),s.end()); } }
Define_Module(CAVApp);

CAVApp::~CAVApp() { cancelAndDelete(startEvent_); }
void CAVApp::initialize(int stage) { DemoBaseApplLayer::initialize(stage); if (stage != 0) return; pid_=par("pseudonym").stdstringValue(); targetRsu_=par("targetRsu").stdstringValue(); nextRsu_=par("nextRsu").stdstringValue(); kem_=crypto_.generateKemKeyPair(); sig_=crypto_.generateSigKeyPair(); SimulationCredentialDirectory::registerSigningKey(pid_,sig_.publicKey); handshakeLatencySignal_=registerSignal("v2rHandshakeLatency"); handoverLatencySignal_=registerSignal("handoverLatency"); cryptoMicrosSignal_=registerSignal("cryptoProcessingMicros"); successSignal_=registerSignal("v2rHandshakeSuccess"); failureSignal_=registerSignal("v2rHandshakeFailure"); startEvent_=new cMessage("startAuthenticatedKeyEstablishment"); scheduleAt(par("startAt"),startEvent_); }
void CAVApp::handleSelfMsg(cMessage* m) { if(m==startEvent_){sendVehicleHello();return;} DemoBaseApplLayer::handleSelfMsg(m); }
std::string CAVApp::helloBytes() const { return "CAV-PQC-v1|VEHICLE_HELLO|"+sessionId_+"|"+pid_+"|"+PqcCrypto::hex(kem_.publicKey)+"|"+PqcCrypto::hex(vehicleNonce_); }
void CAVApp::sendVehicleHello() { vehicleNonce_=crypto_.random(32); const auto ts=nowMs(simTime()); const std::string sid="CAV-PQC-v1/session|"+pid_+"|"+PqcCrypto::hex(kem_.publicKey)+"|"+PqcCrypto::hex(vehicleNonce_)+"|"+std::to_string(ts); sessionId_=PqcCrypto::hex(crypto_.shake256(text(sid))); helloTranscript_=helloBytes()+"|"+std::to_string(ts); const auto begin=std::chrono::steady_clock::now(); const Bytes signature=crypto_.sign(sig_.secretKey,crypto_.shake256(text(helloTranscript_))); const auto micros=std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-begin).count(); auto* m=new CavMsg("VehicleHello"); populateWSM(m); m->setMessageType(VEHICLE_HELLO);m->setSessionId(sessionId_.c_str());m->setSenderPid(pid_.c_str());m->setReceiverPid(targetRsu_.c_str());m->setKemPublicKeyHex(PqcCrypto::hex(kem_.publicKey).c_str());m->setSigningPublicKeyHex(PqcCrypto::hex(sig_.publicKey).c_str());m->setNonceHex(PqcCrypto::hex(vehicleNonce_).c_str());m->setTimestampMs(ts);m->setSignatureHex(PqcCrypto::hex(signature).c_str());m->addBitLength((kem_.publicKey.size()+sig_.publicKey.size()+vehicleNonce_.size()+signature.size())*8);emit(cryptoMicrosSignal_,static_cast<long>(micros));handshakeStarted_=simTime();sendDown(m); }
Bytes CAVApp::deriveSessionKey(const CavMsg& m,const Bytes& secret) const { const std::string ctx="CAV-PQC-v1/v2r-context|"+PqcCrypto::hex(kem_.publicKey)+"|"+m.getKemCiphertextHex()+"|"+PqcCrypto::hex(vehicleNonce_)+"|"+m.getNonceHex()+"|"+pid_+"|"+targetRsu_; return crypto_.hkdfSha384(secret,crypto_.shake256(text(ctx)),"CAV-PQC-v1/session|"+sessionId_); }
void CAVApp::handleServerHello(CavMsg* m) { try { if(std::string(m->getReceiverPid())!=pid_||std::string(m->getSessionId())!=sessionId_) throw std::runtime_error("server binding"); const Bytes rsuKey=SimulationCredentialDirectory::signingKey(m->getSenderPid()); if(rsuKey!=PqcCrypto::unhex(m->getSigningPublicKeyHex())) throw std::runtime_error("RSU credential"); const std::string th=PqcCrypto::hex(crypto_.shake256(text(helloTranscript_))); if(th!=m->getTranscriptHashHex()) throw std::runtime_error("transcript"); const std::string reply="CAV-PQC-v1|SERVER_HELLO|"+sessionId_+"|"+m->getSenderPid()+"|"+m->getKemCiphertextHex()+"|"+m->getNonceHex()+"|"+m->getTranscriptHashHex(); if(!crypto_.verify(rsuKey,crypto_.shake256(text(reply)),PqcCrypto::unhex(m->getSignatureHex()))) throw std::runtime_error("server signature"); const auto begin=std::chrono::steady_clock::now(); sessionKey_=deriveSessionKey(*m,crypto_.decapsulate(kem_.secretKey,PqcCrypto::unhex(m->getKemCiphertextHex()))); const Bytes confirm=crypto_.hkdfSha384(sessionKey_,crypto_.shake256(text(helloTranscript_+"|"+reply)),"CAV-PQC-v1/finished"); emit(cryptoMicrosSignal_,static_cast<long>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-begin).count())); sendFinished(m,confirm); } catch(const std::exception&) { emit(failureSignal_,1L); } }
void CAVApp::sendFinished(CavMsg* sh,const Bytes& confirm) { const std::string reply="CAV-PQC-v1|SERVER_HELLO|"+sessionId_+"|"+sh->getSenderPid()+"|"+sh->getKemCiphertextHex()+"|"+sh->getNonceHex()+"|"+sh->getTranscriptHashHex(); const Bytes hash=crypto_.shake256(text(helloTranscript_+"|"+reply)); const Bytes tag=crypto_.hmacSha384(confirm,text("CAV-PQC-v1/vehicle-finished|"+PqcCrypto::hex(hash)+"|"+sessionId_)); auto* m=new CavMsg("Finished");populateWSM(m);m->setMessageType(FINISHED);m->setSessionId(sessionId_.c_str());m->setSenderPid(pid_.c_str());m->setReceiverPid(targetRsu_.c_str());m->setTranscriptHashHex(PqcCrypto::hex(hash).c_str());m->setFinishedTagHex(PqcCrypto::hex(tag).c_str());m->setTimestampMs(nowMs(simTime()));m->addBitLength((hash.size()+tag.size())*8);sendDown(m); }
void CAVApp::handleFullHandshakeAck(CavMsg* m) { if(std::string(m->getReceiverPid())!=pid_) return; fullHandshakeLatency_=(simTime()-handshakeStarted_).dbl(); emit(handshakeLatencySignal_,fullHandshakeLatency_); }
void CAVApp::handleHandoverOffer(CavMsg* m) { if(handoverComplete_ || !handoverContextKey_.empty()) return; try { if(std::string(m->getReceiverPid())!=pid_||std::string(m->getNextRsuId())!=nextRsu_||m->getExpiryMs()<=nowMs(simTime())) throw std::runtime_error("offer binding"); const Bytes sourceKey=SimulationCredentialDirectory::signingKey(m->getSourceRsuId()); const std::string token="CAV-PQC-v1/handover-token|"+pid_+"|"+m->getNextRsuId()+"|"+m->getContextKeyHashHex()+"|"+std::to_string(m->getTimestampMs())+"|"+std::to_string(m->getExpiryMs())+"|"+m->getNonceHex(); if(!crypto_.verify(sourceKey,crypto_.shake256(text(token)),PqcCrypto::unhex(m->getHandoverTokenSignatureHex()))) throw std::runtime_error("token signature"); handoverContextKey_=crypto_.hkdfSha384(sessionKey_,crypto_.shake256(text("CAV-PQC-v1/handover-context")),"handover-context"); if(PqcCrypto::hex(crypto_.shake256(handoverContextKey_))!=m->getContextKeyHashHex()) throw std::runtime_error("context mismatch"); handoverTokenSignature_=m->getHandoverTokenSignatureHex(); handoverStarted_=simTime(); sendHandoverRequest(m); } catch(const std::exception&) { fallbackUsed_=true; emit(failureSignal_,1L); } }
void CAVApp::sendHandoverRequest(CavMsg* offer) { handoverNonce_=crypto_.random(32); const auto ts=nowMs(simTime()); const std::string request="CAV-PQC-v1/handover-request|"+pid_+"|"+nextRsu_+"|"+offer->getHandoverTokenSignatureHex()+"|"+PqcCrypto::hex(handoverNonce_)+"|"+std::to_string(ts); const Bytes signature=crypto_.sign(sig_.secretKey,crypto_.shake256(text(request))); auto* m=new CavMsg("HandoverRequest");populateWSM(m);m->setMessageType(HANDOVER_REQUEST);m->setSessionId(sessionId_.c_str());m->setSenderPid(pid_.c_str());m->setReceiverPid(nextRsu_.c_str());m->setSourceRsuId(offer->getSourceRsuId());m->setNextRsuId(nextRsu_.c_str());m->setHandoverTokenSignatureHex(offer->getHandoverTokenSignatureHex());m->setContextKeyHashHex(offer->getContextKeyHashHex());m->setNonceHex(PqcCrypto::hex(handoverNonce_).c_str());m->setTimestampMs(ts);m->setExpiryMs(offer->getExpiryMs());m->setSigningPublicKeyHex(PqcCrypto::hex(sig_.publicKey).c_str());m->setSignatureHex(PqcCrypto::hex(signature).c_str());m->addBitLength((handoverNonce_.size()+signature.size())*8);sendDown(m); }
void CAVApp::handleHandoverConfirm(CavMsg* m) { if(handoverComplete_) return; try { if(std::string(m->getReceiverPid())!=pid_) throw std::runtime_error("confirm binding"); const Bytes rsuKey=SimulationCredentialDirectory::signingKey(m->getSenderPid()); const std::string confirm="CAV-PQC-v1/handover-confirm|"+sessionId_+"|"+pid_+"|"+nextRsu_+"|"+PqcCrypto::hex(handoverNonce_)+"|"+m->getNonceHex(); if(!crypto_.verify(rsuKey,crypto_.shake256(text(confirm)),PqcCrypto::unhex(m->getSignatureHex()))) throw std::runtime_error("confirm signature"); sessionKey_=crypto_.hkdfSha384(handoverContextKey_,crypto_.shake256(text(PqcCrypto::hex(handoverNonce_)+"|"+m->getNonceHex()+"|"+std::to_string(m->getTimestampMs()))),"CAV-PQC-v1/handover-session"); const double latency=(simTime()-handoverStarted_).dbl(); handoverComplete_=true; emit(handoverLatencySignal_,latency); writeHandoverResult(latency,true); } catch(const std::exception&) { writeHandoverResult(-1,false); } }
void CAVApp::handleFallback(CavMsg*) { fallbackUsed_=true; writeHandoverResult(-1,false); targetRsu_=nextRsu_; sendVehicleHello(); }
void CAVApp::writeHandoverResult(double latency,bool success) const { static bool initialized=false; const std::string path="../../results/raw/handover_results.csv"; if(!initialized){std::ofstream clear(path,std::ios::trunc);clear<<"run,full_handshake_latency_s,handover_latency_s,handover_success,fallback_used\n";initialized=true;} std::ofstream file(path,std::ios::app); file<<getEnvir()->getConfigEx()->getActiveRunNumber()<<","<<fullHandshakeLatency_<<","<<latency<<","<<(success?1:0)<<","<<(fallbackUsed_?1:0)<<"\n"; }
void CAVApp::onWSM(veins::BaseFrame1609_4* f) { auto* m=dynamic_cast<CavMsg*>(f); if(!m)return; switch(m->getMessageType()){case SERVER_HELLO:handleServerHello(m);break;case FULL_ACK:handleFullHandshakeAck(m);break;case HANDOVER_OFFER:handleHandoverOffer(m);break;case HANDOVER_CONFIRM:handleHandoverConfirm(m);break;case HANDOVER_FALLBACK:handleFallback(m);break;} }
}
